CREATE view HEAD_BACK_ANBAR as  SELECT     NUMBER, TAG - 11 AS HTAG, ANBAR, NUMBER1, DATE_N, TAH, MAS, VAS, N_S, CUST_NO, MOLAH, M_NAGHD, MABL_VAR, MOIN_VAR, MABL_HAV,                      MOIN_HAV, MABL_HAZ, MOIN_HAZ, TAKHFIF, MOIN_KHF, ANBARF, FNUMCO, DEPATMAN, SHIFT, CUST_KIND, USER_NAME, MBAA, SADER,                      SHARAYET , TAG, SGN1usid, sgn2usid, sgn3usid , SGN1, sgn2, sgn3  FROM dbo.HEAD_LST WHERE (TAG - 11 > 0)
